import java.util.*; 
import java.io.*;

public class VariantFour {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            reader.close();
            return;
        }
        int testCount = Integer.parseInt(line.trim());
        String[] aStr = reader.readLine().split(" ");
        String[] bStr = reader.readLine().split(" ");
        int[] a = new int[3], b = new int[3];
        for (int i = 0; i < 3; i++) {
            a[i] = Integer.parseInt(aStr[i]);
            b[i] = Integer.parseInt(bStr[i]);
        }

        int alicePoints = 0, bobPoints = 0;

        if (a[0] != 0) alicePoints += Math.min(a[0], b[1]);
        if (a[1] != 0) alicePoints += Math.min(a[1], b[2]);
        if (a[2] != 0) alicePoints += Math.min(a[2], b[0]);

        int[] bCopy = b.clone();

        if (bCopy[0] != 0) {
            bobPoints += Math.min(bCopy[0], a[1]);
            bCopy[0] -= Math.min(bCopy[0], a[1]);
            if (bCopy[0] != 0) bobPoints += Math.min(bCopy[0], a[0]);
        }
        if (bCopy[1] != 0) {
            bobPoints += Math.min(bCopy[1], a[2]);
            bCopy[1] -= Math.min(bCopy[1], a[2]);
            if (bCopy[1] != 0) bobPoints += Math.min(bCopy[1], a[1]);
        }
        if (bCopy[2] != 0) {
            bobPoints += Math.min(bCopy[2], a[0]);
            bCopy[2] -= Math.min(bCopy[2], a[0]);
            if (bCopy[2] != 0) bobPoints += Math.min(bCopy[2], a[2]);
        }

        System.out.println((testCount - bobPoints) + " " + alicePoints);
        reader.close();
    }
}
